const l=[{id:"stoic-epictetus-iep",title:"S09 · Seddon · Epictetus · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epictetus’s distinction between what is and is not up to us offers philosophical guidance for directing effort toward judgments, aims, and conduct.",limitation:"History and philosophy, not psychological evidence that thoughts or conduct are fully voluntary. Disability, illness, coercion, and resources constrain action."},{id:"stoic-seneca-iep",title:"S10 · Wagoner · Seneca · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca’s philosophical account of anger distinguishes involuntary first movements from later assent.",limitation:"This is historical philosophy, not a validated complete model of emotion. It does not mean panic or trauma symptoms can be chosen away or are moral failures."},{id:"stoic-week-handbook",title:"S08 · Stoicism Today · Stoic Week 2016 handbook",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"Documents the control distinction, adversity contemplation, wider perspective, and a fair five-to-ten-minute evening review before getting into bed.",limitation:"A practitioner manual, not a trial of isolated rituals or optimal doses. No verified independent effect for control-sort, negative imagery, cosmic perspective, or evening review."},{id:"stoic-planning",title:"S03 · Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests with 8,461 participants found average goal-attainment benefits from specified situation-response plans, d = 0.65 [0.60, 0.70].",limitation:"Varied goals, designs, and comparisons; not restricted to modern preregistered randomized trials. This is not a success percentage, a guarantee, or evidence for negative visualization."},{id:"stoic-mcii",title:"S04 · Wang, Wang & Gai · 2021 · Mental contrasting with planning",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles provided 24 independent estimates from 15,907 participants. Desired outcome, present obstacle, and if–then response produced average goal-attainment g = 0.336 [0.229, 0.443].",limitation:"Meaningful heterogeneity, I² = 59.3%, and uneven quality limit precision. This does not isolate negative visualization, prove every goal feasible, or validate ODA’s brief adaptation."},{id:"stoic-thought-record",title:"S11 · NHS · Thought record · Every Mind Matters",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/",type:"guidance",finding:"Seven prompts separate situation, feelings, thought, evidence for, evidence against, a realistic alternative, and feelings afterward. A neutral conclusion can be appropriate.",limitation:"Official self-help guidance, not an isolated effect-size study. It does not require positivity or interpreting actual mistreatment as harmless."},{id:"stoic-cbt",title:"S01 · Hofmann et al. · 2012 · Review of CBT meta-analyses",url:"https://www.europsy.net/app/uploads/2017/08/Hofmann-2012-The-efficacy-of-CBT-a-review-of-meta-analyses.pdf",type:"research",finding:"The authors identified 269 meta-analyses and discussed a representative 106, with strong disorder-specific evidence for several anxiety-related conditions, anger, and stress.",limitation:"A narrative overview, without one pooled CBT effect or participant count. Treatment evidence does not transfer to a Stoic lesson or isolate a brief thought record."},{id:"stoic-kross-self-talk",title:"S05 · Kross et al. · 2014 · Self-talk as a regulatory mechanism",url:"https://rascl.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven studies totaling 585 participants examined non-first-person introspection. Study 1a used 60 seconds of reflection and found increased reported self-distancing.",limitation:"Convergent experiments within one research program, not seven independent clinical trials. Using a name is not a proven treatment, and the mild current-situation ODA exercise is an adaptation."},{id:"stoic-kross-distancing",title:"S06 · Murdoch et al. · 2023 · Self-distanced reflections meta-analysis",url:"https://onlinelibrary.wiley.com/doi/full/10.1002/smi.3199",type:"research",finding:"25 experiments in 17 papers, with 2,397 participants, found a modest pooled effect, g = 0.19 [0.05, 0.33], across varied outcomes.",limitation:"Predominantly young, apparently healthy adults; uncertain quality and substantial heterogeneity. Prediction interval crossed zero. Objective outcomes were nonsignificant, and cosmic or ten-year rituals were not isolated."},{id:"stoic-distancing-sleep",title:"S16 · Riddell et al. · 2023 · Stressor reflections and sleep",url:"https://onlinelibrary.wiley.com/doi/10.1002/smi.3201",type:"research",finding:"A preregistered reflection experiment did not support a sleep benefit from distancing. Sleep-quality change favored immersion; sleep-duration difference was nonsignificant.",limitation:"318 baseline participants and 257 analyzed, with 51 distanced participants excluded for first-person writing. Inconsistent table and narrative signs prevent a directional well-being claim."},{id:"stoic-training-trial",title:"S13 · Maclellan & Derakshan · 2021 · Training in high worriers",url:"https://link.springer.com/article/10.1007/s10608-020-10183-4",type:"research",finding:"45 high worriers were randomized across eight-session Stoic training, a combined training arm, and an active one-back control. The abstract reports changes in rumination and self-efficacy.",limitation:"A small study with abstract-only access here. Exact effects, confidence intervals, attrition, and registration were not verified. It does not isolate a ritual or establish treatment for diagnosed anxiety."},{id:"stoic-training-thesis",title:"S15 · King · 2025 · Modern Stoicism and mental health thesis",url:"https://pure.royalholloway.ac.uk/en/publications/modern-stoicism-and-mental-health-a-randomised-controlled-trial/",type:"research",finding:"119 nonclinical adults were allocated to two-week online Stoic training or a waitlist. The institutional abstract reports favorable complete-case changes on some mental-health measures.",limitation:"One unpublished doctoral thesis, not a peer-reviewed efficacy consensus. Completer counts, effects, intervals, and registration were unverified; waitlist comparison does not establish isolated ritual effects or psychotherapy equivalence."}],r=[{schemaVersion:2,revision:2,id:"stoic-1",courseId:"stoic",locale:"en",title:"Still checking for an answer you cannot decide?",goal:"Create one useful piece for a chosen goal while its outcome remains uncertain.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Refreshing the reply again? Give the action that could help your goal some of that attention.",reason:{id:"stoic-1-reason",label:"What useful act has checking the outcome displaced?",kind:"text",maxLength:160,optional:!0,suggestions:["Build evidence for my goal","Stop refreshing for reassurance","Ask for practical help"]},why:{id:"stoic-1-why",label:"What useful act has checking the outcome displaced?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["An outcome can matter without being yours to determine. Epictetus used this distinction to direct effort toward conduct rather than reputation or results. It is philosophy, not proof that every thought and action is completely voluntary. Health, coercion, disability, and resources can limit what you can do.","Choose one goal and one useful act for this course’s continuing experiment. Separate what you can attempt, what needs support, and what others decide. Then do your feasible part. A portfolio sentence exists even if no employer replies. Use outcomes as information; you do not have to stop caring about them."],example:{title:"Daniel’s evidence sentence",text:"At Monday lunch, Daniel has refreshed an application inbox four times. He wants useful project evidence for a job, so at his desk he writes one concrete portfolio sentence. It describes a checklist he improved and how it was used. He records the sentence. The inbox stays empty, and he still feels uncertain."}},move:{invitation:"Choose one useful act while the outcome stays uncertain.",instructions:["Sort action, needed support, and outcome without demanding total control.","Do your feasible part and record it."],prompts:[],suggestions:{action:["Write one relevant project evidence sentence","Send one appropriate clarification question","Make one practical support request"],minimum:["Produce one usable evidence sentence","Send one clear question","Make one specific support request"],cue:["When I return from lunch","At my next safe opening","Before the next project step"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use a voice note for the sentence","Choose a smaller relevant contribution","Ask for help with access"],observation:["The useful piece I produced","The question and any response","What support I requested"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one relevant project evidence sentence",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When I return from lunch",placeHint:"At my usual work surface",obstacleHint:"My available energy or resources are limited.",fallbackHint:"Use a voice note for the sentence",observationHint:"The useful piece I produced"},stopRule:"Do not practice through danger. Seek protection or support when action is constrained.",accessibleAlternative:"Use dictation, assisted communication, a safe boundary, or practical support."},result:{question:"Did you do your feasible minimum?",observationPrompt:"What did you produce or ask, and what remains undecided?"},judgment:{primary:{id:"stoic-1-decision",scenario:"Daniel has ten minutes after lunch and no urgent reply due. His application opening is clear, but a recruiter asked for specific project evidence. He has a relevant example to describe.",question:"Where should these minutes go?",options:[{id:"keep-checking",text:"Check the inbox every few minutes so a potential employer receives an immediate response.",feedback:"Being reachable may matter. Here no urgent reply is expected, and useful evidence is available to create. Choose a check time and give the sentence a turn."},{id:"write-evidence",text:"Write the relevant evidence sentence now, then check the inbox at a chosen time.",feedback:"This invests in a feasible act without promising an offer. Record the sentence, keep necessary contact access, and treat a later response as information."},{id:"revise-opening",text:"Revise the opening paragraph for ten minutes so the application presents his project more clearly.",feedback:"A clearer opening helps when the introduction is confusing. Here the opening is clear and specific evidence is missing. Produce that evidence now; revise the introduction if later feedback identifies a problem."}],bestOptionId:"write-evidence"}},carry:{takeaway:"Care about the outcome. Give your feasible part an actual attempt.",followUp:{questionId:"stoic-1-return",question:"What useful piece or request happened, and what support constraint remained?",observationPrompt:"Name the piece or request, or note why it remained unavailable.",adjustmentPrompt:"What support or cue fits the next attempt?"}},goDeeper:{sections:[{heading:"A guide to effort, with an influence middle",paragraphs:["The scholarly account of Epictetus describes judgments, aims, and conduct as up to us, contrasted with externals such as reputation [S09]. He was born enslaved in Hierapolis and later taught at Nicopolis; Arrian recorded his teachings. Those historical facts explain the tradition, not the effectiveness of a modern worksheet. The distinction can orient effort without establishing that a person always has complete voluntary control over attention, feelings, or conduct.","ODA uses an adaptation with room between total control and helplessness: what you can attempt, what you might influence with help, and what you cannot determine alone. The Stoic Week handbook documents the control distinction as a practice [S08]. It is guidance, not an isolated trial. A workplace problem might need collective action. A health problem may need assessment and care. A harmful interaction may require protection. None of these becomes a private attitude failure because another person or circumstance contributes to the outcome."]},{heading:"Make your part observable",paragraphs:["Gollwitzer and Sheeran reviewed 94 independent planning tests involving 8,461 participants [S03]. Specifying a situation and intended response improved goal attainment on average. The studies varied in goals, designs, and comparisons and were not restricted to modern preregistered randomized trials. Their standardized effect does not mean a percentage chance of success. It does not test a control-sort, prove Stoicism effective, or guarantee that a cue overrides fatigue or lack of resources.","Use that planning structure for a modest act: after lunch at your work surface, produce one usable evidence sentence. Opening a document is preparation. Rehearsing an interview answer is also preparation and should be named that way, with a later opportunity to use it. An external reply is not your completion condition. Still record relevant feedback rather than discarding it as outside your control. Your next plan should respond to available information, needed support, and the chosen life direction."]}],sourceIds:["stoic-epictetus-iep","stoic-week-handbook","stoic-planning"]}},{schemaVersion:2,revision:2,id:"stoic-2",courseId:"stoic",locale:"en",title:"Their silence is still an unanswered question",goal:"Check one interpretation, then use a grounded clarification or protective response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The reply is late. Are you acting on facts, or guessing why?",reason:{id:"stoic-2-reason",label:"What has this untested interpretation made you do?",kind:"text",maxLength:160,optional:!0,suggestions:["Clarify a real deadline","Stop acting on a guess","Protect a needed boundary"]},why:{id:"stoic-2-why",label:"What has this untested interpretation made you do?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A missed reply is a fact. “They do not respect me” is an interpretation, and it may need evidence. That does not mean the event cannot hurt. Seneca’s account of anger distinguished an involuntary first reaction from later endorsement. It was philosophy, not a complete scientific explanation of distress.","Return to the same goal and act. Check evidence for and against one story blocking it. A fair alternative can be “I do not know yet.” Then clarify a real deadline, correct a fact, or protect a boundary. Keep actual mistreatment visible. Feeling less upset is optional; the grounded response is the test."],example:{title:"Daniel checks the missing reply",text:"On Tuesday at his desk, Daniel sees two missed replies about a reference. He assumes his colleague thinks his work is weak. He cannot verify that reason, but the deadline is real. He sends one question asking whether the reference can arrive Thursday. The colleague has not answered by evening. Daniel records the question and the uncertainty."}},move:{invitation:"Check one story, then take a grounded next step.",instructions:["Name the fact and the interpretation separately.","Use one clarification, factual correction, or safe boundary."],prompts:[],suggestions:{action:["Send one factual clarification about my goal","Use one evidence-based project correction","Make one safe boundary request"],minimum:["Send one clear deadline question","Produce one corrected sentence","State one specific safe limit"],cue:["Before my next reply","At my next project check-in","When the deadline needs clarification"],place:["In a safe message thread","At my usual work surface","In an accessible private space"],minutes:[2,5],fallback:["Choose another safe clarification route","Use known facts without guessing motives","Get support before further contact"],observation:["My question and the actual reply","The fact I corrected","The limit I communicated"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Send one factual clarification about my goal",minimum:"Send one clear deadline question",minutes:2,cueHint:"Before my next reply",placeHint:"In a safe message thread",obstacleHint:"Contact is unsafe, or the other person does not reply.",fallbackHint:"Choose another safe clarification route",observationHint:"My question and the actual reply"},stopRule:"Real harm needs protection. Do not replace evidence of mistreatment with a comforting guess.",accessibleAlternative:"Use your usual communication method, a safe written response, or support instead of contact."},result:{question:"Did you use your grounded response?",observationPrompt:"What did you actually say, and what response came back?"},judgment:{primary:{id:"stoic-2-decision",scenario:"A colleague missed two promised reference replies. Daniel needs the reference Thursday. He has no evidence about the reason for the delay.",question:"Which response checks the story and addresses the deadline?",options:[{id:"comfort-guess",text:"Assume the colleague is overloaded and keep waiting so the relationship stays comfortable.",feedback:"Overload is possible, but it is still an unverified explanation. The missed commitments and deadline need a grounded question, even if the colleague’s motive remains unknown."},{id:"withdraw-work",text:"Reduce cooperation for now so the colleague notices the effect of the missing replies.",feedback:"A boundary may become necessary. With the reason unknown, withdrawing cooperation first adds another assumption. Clarify the deadline and blocker before deciding a suitable limit."},{id:"clarify-deadline",text:"Name the missed replies and ask whether Thursday is workable or another route is needed.",feedback:"This checks missing information while respecting a real pattern. A neutral alternative is not forced positivity. Record the answer, including silence, and decide what support or boundary follows."}],bestOptionId:"clarify-deadline"}},carry:{takeaway:"Check the interpretation and address the real fact. A pleasant guess is still a guess.",followUp:{questionId:"stoic-2-return",question:"Did new evidence support or challenge your interpretation, leave it unknown, or reveal harm?",observationPrompt:"What evidence changed, or is the motive still unknown?",adjustmentPrompt:"Clarify again, change the plan, or get support?"}},goDeeper:{sections:[{heading:"First reactions and tested interpretations",paragraphs:["Seneca’s account of anger separates involuntary first movements from the assent associated with full anger [S10]. It is a historical philosophical distinction, not a complete experimental model of emotion. Panic, pain, trauma symptoms, and an automatic thought are not evidence that you failed to choose correctly. Actual events, circumstances, and interpretations can all matter. Looking at one interpretation is a practical lens, not an exclusive account of why someone suffers.","The NHS thought record offers seven prompts: situation, feelings, thought, evidence for, evidence against, a realistic alternative, and feelings afterward [S11]. Evidence on both sides matters. An alternative can be neutral rather than reassuring. In the example, “The deadline has been missed and I do not know why” keeps both the problem and uncertainty visible. ODA’s short check and action simplify that guidance; they do not reproduce therapy or require the feelings afterward to improve."]},{heading:"A therapy resemblance does not transfer efficacy",paragraphs:["Hofmann and colleagues identified 269 meta-analyses and discussed a representative 106 in their review of cognitive behavioral therapy [S01]. The overview described substantial disorder-specific evidence, particularly for several anxiety-related conditions, anger, and general stress. It did not give one pooled effect or participant count for all CBT. Those findings belong to the treatments studied, not every exercise that resembles a treatment idea. Reading a philosophy lesson does not deliver clinical CBT.","A thought record is officially described self-help guidance [S11], but that source does not establish its isolated clinical effect size. Use it to separate evidence from interpretation and choose an appropriate response. Do not turn every late message into a cognitive error or reinterpret abuse as harmless. If distress is severe, persistent, or affecting daily functioning, qualified support may be the appropriate action. The record can include unchanged anger, a factual clarification, or a protective choice without treating any of them as a failed lesson."]}],sourceIds:["stoic-seneca-iep","stoic-thought-record","stoic-cbt"]}},{schemaVersion:2,revision:2,id:"stoic-3",courseId:"stoic",locale:"en",title:"When the usual interruption arrives, have a response",goal:"Use one realistic obstacle response to keep your existing useful act feasible.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your plan fits a cooperative day. What will you do when its familiar interruption appears?",reason:{id:"stoic-3-reason",label:"Which real obstacle needs a response this time?",kind:"text",maxLength:160,optional:!0,suggestions:["Restart after the usual interruption","Protect a short work slot","Ask for help with access"]},why:{id:"stoic-3-why",label:"Which real obstacle needs a response this time?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Imagining trouble and planning a response are different. Research on planning links a specific obstacle or opening to a feasible act. It does not establish that vivid negative visualization makes you resilient. The useful ingredient here is a response you could actually use, not a worse imagined scene.","Keep your experiment’s direction and act. Pick one mild, realistic friction point from your record. Write an if–then response and use it when needed. Imagery is optional. Do not relive catastrophe or trauma. If the obstacle never appears, record no occasion for that response, while recording any ordinary task attempt separately."],example:{title:"Daniel restarts after a call",text:"Before Wednesday’s portfolio slot, Daniel plans for the call that often interrupts lunch. His response is to restart with one usable evidence sentence when the call ends. The call happens at his desk. He returns, dictates the sentence, and saves it. He gets no further that afternoon, but records the response he actually used."}},move:{invitation:"Prepare one realistic response for your existing act’s friction.",instructions:["Name one likely obstacle without vivid imagery.","Use the response if needed, then record it."],prompts:[],suggestions:{action:["Use my restart response if interrupted","Ask for a workable project boundary","Use my access support if needed"],minimum:["Produce one usable evidence sentence","Make one specific boundary request","Make one specific access request"],cue:["When the usual interruption ends","Before my protected work slot","When the access barrier appears"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use dictation for the useful sentence","Choose the next feasible work opening","Ask a trusted person for assistance"],observation:["Whether interruption and restart happened","Whether I used my response","The usable piece I produced"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use my restart response if interrupted",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When the usual interruption ends",placeHint:"At my usual work surface",obstacleHint:"The response needs time or access I do not have.",fallbackHint:"Use dictation for the useful sentence",observationHint:"Whether interruption and restart happened"},stopRule:"Keep eyes open if preferred. Stop or skip if panic, dissociation, or intrusive memories arise.",accessibleAlternative:"Plan without imagery. Choose a smaller act, practical support, or a safe pause."},result:{question:"Did you use your response when needed?",observationPrompt:"Did the obstacle occur, and what did you actually do?"},judgment:{primary:{id:"stoic-3-decision",scenario:"Daniel’s lunchtime portfolio slot is often interrupted by a brief required call. Care duties fill the earlier slot. Two minutes usually remain after the call. The evidence is needed this evening.",question:"Which response fits that predictable obstacle?",options:[{id:"restart-small",text:"Take the required call, then produce one useful sentence when it ends.",feedback:"This respects the required call and the remaining time. The response is feasible and observable. Record whether the obstacle appeared and whether the restart actually happened."},{id:"same-minimum-tomorrow",text:"Use tomorrow’s two-minute portfolio slot instead, keeping lunch free after the required call.",feedback:"Moving the same small act can protect recovery when time or capacity is unavailable. Here two minutes remain and the evidence is needed tonight. Test the restart now; adapt if capacity changes."},{id:"move-before-lunch",text:"Move the portfolio slot before lunch and arrange to take the required call from there.",feedback:"Moving the slot could avoid the interruption if earlier time were free. Here care duties occupy it. Take the required call and test the useful sentence in the remaining lunch time."}],bestOptionId:"restart-small"}},carry:{takeaway:"Prepare a response you can use, not a catastrophe you can replay.",followUp:{questionId:"stoic-3-return",question:"Did the predicted obstacle happen, and was your response available?",observationPrompt:"Name the obstacle, available restart opening, and response used; untested is valid.",adjustmentPrompt:"Keep the response, shrink it, or change the setting?"}},goDeeper:{sections:[{heading:"Ancient adversity practice and modern planning",paragraphs:["The Stoic Week handbook documents adversity contemplation as a practice [S08]. It is practitioner guidance, not evidence for an isolated negative-visualization effect. Its rationale cannot be presented as a proven mechanism or permission to conduct exposure treatment alone. ODA instead offers a mild everyday obstacle, optional imagery, and a feasible response. Those changes are adaptations. You can plan entirely in words without revisiting any upsetting memory.","Stand-alone implementation intentions connect a specific situation to an intended behavior [S03]. The 2006 review covered 94 independent tests with 8,461 participants and found average goal-attainment benefits across different contexts. It did not show that scripting overrides fatigue, disability, or unavailable resources. A response might be a smaller useful task, a boundary, or support. If the obstacle is danger, address safety rather than asking how to persist. Stop an imagery exercise that brings panic, dissociation, or intrusive memories; a plan without imagery remains available."]},{heading:"The obstacle is not always inside you",paragraphs:["Wang and colleagues reviewed mental contrasting with implementation intentions [S04]. The sequence joins a feasible wish, its desired outcome, a present obstacle, and an if–then response. Across 21 articles and 24 independent estimates with 15,907 participants, average goal attainment improved modestly, g = 0.336. Studies and delivery varied, with meaningful heterogeneity and uneven quality. The findings do not establish an optimal two-minute dose, negative imagery alone, or this ODA version.","A required call, unavailable transport, care duty, or inaccessible equipment is a real condition, not merely a mindset problem. Name it accurately. Your response can be to request help, change the opportunity, or stop an unsuitable plan. Test one condition rather than adding several new rituals. Keep preparation and use separate: writing a restart plan does not prove a restart occurred. If no interruption appears, the backup was not tested. Record that uncertainty and the ordinary act on its own terms."]}],sourceIds:["stoic-week-handbook","stoic-planning","stoic-mcii"]}},{schemaVersion:2,revision:2,id:"stoic-4",courseId:"stoic",locale:"en",title:"A sharp reply is ready. Is it useful?",goal:"Use optional name-based coaching, then a factual response that serves your chosen direction.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"You have the comeback ready. What response would help the goal after these ten seconds pass?",reason:{id:"stoic-4-reason",label:"What would a factual response protect or move forward?",kind:"text",maxLength:160,optional:!0,suggestions:["Protect useful collaboration","Correct the record","Keep a clear boundary"]},why:{id:"stoic-4-why",label:"What would a factual response protect or move forward?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Using your name can create distance during brief reflection. Experiments have studied this, but wider evidence shows modest, varied effects. Calm is not guaranteed. Cosmic and ten-year viewpoints are different exercises without a specific established benefit here.","Use the tool when a heated moment blocks your direction. Optional 60-second preparation: “Daniel, which fact needs correcting, and what request would help?” Substitute your name, or skip it. Then use one factual sentence, request, or boundary. Stepping back must not erase harm. Record the response, even if anger remains."],example:{title:"Daniel returns to the facts",text:"On Thursday’s safe project call, Daniel hears that his checklist caused a delay. He wants to fire back. He asks himself by name what would help the work, then states the actual handoff date and asks which step needs changing. The colleague stays irritated. Daniel records his sentence and request rather than claiming the conflict is solved."}},move:{invitation:"Borrow distance if useful, then return to a factual act.",instructions:["If useful, coach yourself by name for 60 seconds. This is preparation.","Use one factual sentence, request, or safe boundary."],prompts:[],suggestions:{action:["Use one factual correction and request","State one clear project boundary","Ask one grounded clarification question"],minimum:["Use one factual sentence","State one specific safe limit","Send one clear question"],cue:["Before my next heated reply","When inaccurate blame is repeated","At my next safe project check-in"],place:["At my usual work surface","In a safe message thread","In the safe meeting space"],minutes:[2,5],fallback:["Use a safe written factual response","Pause contact and get support","Choose another safe opening"],observation:["The sentence I actually used","The request and actual response","Whether a boundary still needs support"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use one factual correction and request",minimum:"Use one factual sentence",minutes:2,cueHint:"Before my next heated reply",placeHint:"At my usual work surface",obstacleHint:"The interaction is unsafe or the pause increases distress.",fallbackHint:"Use a safe written factual response",observationHint:"The sentence I actually used"},stopRule:"Choose an everyday situation. Stop or skip if panic, dissociation, or intrusive memories arise.",accessibleAlternative:"Keep eyes open, skip reflection, or use an assisted factual response or support."},result:{question:"Did you use your chosen factual response?",observationPrompt:"What did you say or set, and what followed?"},judgment:{primary:{id:"stoic-4-decision",scenario:"Daniel is blamed inaccurately again on a safe call. The wrong date is delaying the next handoff, and he knows the actual date. After a brief pause, he wants the work moving and the record corrected.",question:"Which response uses distance without avoiding the issue?",options:[{id:"let-pass",text:"Let the accusation pass so the team can focus on delivery rather than this conflict.",feedback:"Keeping work moving matters. But silence leaves a relevant inaccurate fact uncorrected. State the handoff date and a next-step request, with a boundary if needed."},{id:"facts-request",text:"State the handoff date, ask what needs changing, and set a limit if blame continues.",feedback:"This returns from reflection to a relevant act. A factual correction and request protect the task without requiring calm. A boundary remains available if the pattern continues."},{id:"separate-follow-up",text:"Request a separate discussion about the repeated blame, then continue the call without correcting the date.",feedback:"A separate discussion can address a recurring pattern. Here the inaccurate date also affects the current task. Correct it briefly now, then arrange the wider discussion if needed."}],bestOptionId:"facts-request"}},carry:{takeaway:"A pause earns its place when it helps you choose a useful response.",followUp:{questionId:"stoic-4-return",question:"Did name-based preparation help, get in the way, or feel unnecessary?",observationPrompt:"What tool did you use or skip, and what factual response followed?",adjustmentPrompt:"Keep the tool, drop it, or strengthen support?"}},goDeeper:{sections:[{heading:"What name-based reflection studied",paragraphs:["Kross and colleagues reported seven studies with 585 participants [S05]. In study 1a, 56 undergraduates reflected on a recent upsetting experience for 60 seconds using their name and non-first-person pronouns instead of first-person language. Reported self-distancing increased. Later experiments examined stressful social tasks and performance. These are convergent experiments within one research program, not seven independent clinical randomized trials or evidence that using your name treats anxiety.","This lesson changes the task to a mild current situation and adds a factual action afterward. That is an ODA adaptation, not the original protocol. There is no need to retrieve a painful memory, close your eyes, or visualize yourself from space. If the wording feels strange or destabilizing, skip it. You can ask directly what the task requires, use a safe written response, or seek support. The real response is a separate act; reflecting or drafting alone is preparation."]},{heading:"Modest effects and no sleep promise",paragraphs:["Murdoch and colleagues pooled 25 experiments in 17 papers involving 2,397 adults [S06]. The overall self-distancing effect was modest, g = 0.19, with a 95% confidence interval of 0.05 to 0.33. Evidence quality was uncertain, participants were mostly young and apparently healthy, and results varied substantially. The prediction interval crossed zero. Objective outcomes in four experiments were nonsignificant. These results do not establish superiority for people with greater distress or a specific effect for cosmic or ten-year imagery.","A preregistered reflection study did not support distancing as a sleep intervention [S16]. Sleep-quality change favored immersion, sleep-duration difference was nonsignificant, and asymmetric exclusions complicated interpretation. Its well-being table and narrative had inconsistent signs, so no directional well-being claim is justified here. Choose this tool for an optional perspective shift, not better sleep or reliable emotional relief. Keep the seriousness of the issue visible and judge its practical fit by whether it helps a grounded action."]}],sourceIds:["stoic-kross-self-talk","stoic-kross-distancing","stoic-distancing-sleep"]}},{schemaVersion:2,revision:2,id:"stoic-5",courseId:"stoic",locale:"en",title:"One rough attempt is not your whole character",goal:"Review your latest attempt fairly and use one concrete correction at the next opportunity.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still replaying what went wrong? Find the one change your next attempt can actually use.",reason:{id:"stoic-5-reason",label:"What specific condition needs changing, rather than another replay?",kind:"text",maxLength:160,optional:!0,suggestions:["Learn from the actual attempt","Make one practical correction","Stop judging my whole character"]},why:{id:"stoic-5-why",label:"What specific condition needs changing, rather than another replay?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["The Stoic handbook’s evening review asks what went wrong, what went well, and what could change. It is documented guidance, not an independently proven treatment or sleep aid. Keep the review specific. “I missed the agreed date” offers a correction; “I am useless” gives no useful next step.","Use your experiment’s latest record. Keep one part that served its purpose and change one condition that did not. Then use that correction in the next act. Reviewing is learning or preparation; it does not mean the later action happened. Skip a separate nightly ritual if the existing return is enough."],example:{title:"Daniel uses the review",text:"At Friday lunch, Daniel reviews Thursday’s call at his desk. He corrected the date but omitted the supporting note. He credits the correction and chooses one change: include the evidence line in his follow-up. He sends it that afternoon. The disagreement remains. His record distinguishes reviewing from sending the actual corrected message."}},move:{invitation:"Use your latest record to choose and try one correction.",instructions:["Name one useful part and one specific mismatch.","Use one correction in the next act."],prompts:[],suggestions:{action:["Use one project correction from my review","Make one suitable repair from my record","Use the changed cue for my useful act"],minimum:["Send one corrected project sentence","Make one specific repair request","Produce one usable evidence sentence"],cue:["At my next project follow-up","At my next safe repair opening","At the revised cue I selected"],place:["In a safe message thread","At my usual work surface","In my accessible planning space"],minutes:[2,5],fallback:["Use a smaller factual correction","Choose another safe opening","Get support instead of replaying"],observation:["The correction I actually used","What the changed condition allowed","The request and actual response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use one project correction from my review",minimum:"Send one corrected project sentence",minutes:2,cueHint:"At my next project follow-up",placeHint:"In a safe message thread",obstacleHint:"The review becomes repetitive or the correction is unsafe.",fallbackHint:"Use a smaller factual correction",observationHint:"The correction I actually used"},stopRule:"Stop, shorten, or move reviews that feed rumination or disrupt sleep. Protect safety.",accessibleAlternative:"Use a brief spoken or assisted review, the saved return, or support instead of another ritual."},result:{question:"Did you use the correction you chose?",observationPrompt:"What did you change in the actual act?"},judgment:{primary:{id:"stoic-5-decision",scenario:"Daniel’s evening work slot failed twice when care duties ran late. He still wants project evidence. Lunch offers two safe minutes at his desk.",question:"What makes the review useful?",options:[{id:"same-plan",text:"Record the late care duties and repeat the evening slot to build more consistency.",feedback:"The record is honest, but the condition has repeatedly failed. Keep the direction and test the available lunch minimum instead of asking the same slot to work again."},{id:"make-up",text:"Record the missed slot and plan a longer weekend session to make up the work.",feedback:"A longer session may be useful if feasible. It does not test the recurring cue problem. Try the small available slot before adding compensatory demands."},{id:"cue-change",text:"Credit his care commitment and move one evidence sentence to the available lunch cue.",feedback:"This names a real constraint, preserves what he did, and changes one condition. The review is separate from the next attempt; record whether the lunch act actually happens."}],bestOptionId:"cue-change"}},carry:{takeaway:"Use a fair review to change one condition, then test it in the next act.",followUp:{questionId:"stoic-5-return",question:"Was your changed condition tested, and what did it enable?",observationPrompt:"Name the correction and act, or mark the condition not tested.",adjustmentPrompt:"Keep the correction, change the cue, or seek support?"}},goDeeper:{sections:[{heading:"The review is guidance, not a verdict",paragraphs:["The Stoic Week handbook describes five to ten minutes of evening review before getting into bed [S08]. The three questions ask what went wrong, what went well, and what could be different. It recommends assessing yourself fairly, as you would a friend. This is a documented practitioner procedure, not an empirically established optimal dose or a trial of the review by itself. A shortened ODA return and moving the review earlier are adaptations.","Review the chosen experiment, rather than putting every part of your character on trial. Keep an observable slip, a useful contribution, and one specific change. Do not force forgiveness, an apology, or a warm feeling. A repair is appropriate when you caused harm; protection may be appropriate when harm was done to you. If a review becomes punitive, repetitive, or disruptive to sleep, shorten, move, or stop it. The goal here is an actionable correction, not guaranteed relief or an extra nightly obligation."]},{heading:"Direct Stoic research exists, with limits",paragraphs:["Direct controlled research on Stoic training remains preliminary. Maclellan and Derakshan randomized 45 high worriers among eight-session Stoic training, combined training, and an active control [S13]. Their abstract reported changes in rumination and self-efficacy. It does not establish which component helped or whether an isolated evening review treats diagnosed anxiety. A small training study cannot tell you that repeating this review will reliably change symptoms.","King’s 2025 doctoral thesis allocated 119 nonclinical adults to two-week online Stoic training or a waitlist [S15]. Its institutional abstract reported favorable complete-case changes on some mental-health measures. An unpublished thesis with a waitlist comparison provides early evidence, rather than a peer-reviewed consensus. Neither study establishes that this brief ODA adaptation reproduces the training. Try one fair correction if it suits you, record what happens, and seek qualified help when distress persists or impairs daily functioning. The record should identify a condition actually changed and an act actually tried; a new plan alone leaves the correction untested."]}],sourceIds:["stoic-week-handbook","stoic-training-trial","stoic-training-thesis"]}},{schemaVersion:2,revision:2,id:"stoic-6",courseId:"stoic",locale:"en",title:"Busy all week. Did your priority get a turn?",goal:"Use your records to keep one useful act and one workable condition for next week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Busy week. Which recorded act served your direction?",reason:{id:"stoic-6-reason",label:"What will get less time so your priority gets a turn?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the useful minimum","Use the cue that worked","Drop unhelpful extra rituals"]},why:{id:"stoic-6-why",label:"What will get less time so your priority gets a turn?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Choosing an easy task and choosing a relevant act are different. Mental contrasting and planning research joins a feasible wish, its outcome, a real obstacle, and a specific response. Average benefits are modest and varied. The method does not guarantee success or turn every obstacle into a personal fault.","Consolidate your same experiment. Read the actual attempts, including unavailable openings and pauses. Keep the useful act and cue; change one condition if needed. Then try the next minimum. Drop tools that did not help. An outcome remains uncertain, but its feedback can still change the plan. Support or stopping remains legitimate."],example:{title:"Daniel keeps what worked",text:"At Monday lunch the next week, Daniel checks his records. Two usable sentences came from the short desk slot. Another attempt stopped when access failed. He keeps the slot, asks for the missing access, and produces one new evidence sentence. He drops extra imagery. The application is still pending, but his next plan uses the observed conditions."}},move:{invitation:"Keep the relevant act. Choose its next workable opportunity.",instructions:["Use your records to keep or change one condition.","Do the useful minimum; leave other tools optional."],prompts:[],suggestions:{action:["Repeat my useful project evidence act","Repeat my grounded clarification act","Use the support request my record suggests"],minimum:["Produce one usable evidence sentence","Send one clear question","Make one specific access request"],cue:["When I return from lunch","At my next safe project follow-up","Before my next project attempt"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use my tested smaller version","Choose the next accessible opening","Get support or stop this unsuitable plan"],observation:["The relevant piece I produced","Whether my chosen cue occurred","What the tested condition allowed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful project evidence act",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When I return from lunch",placeHint:"At my usual work surface",obstacleHint:"The old minimum or cue no longer fits my circumstances.",fallbackHint:"Use my tested smaller version",observationHint:"The relevant piece I produced"},stopRule:"Keep safety and needed recovery ahead of persistence. Change, pause, or stop unsuitable plans.",accessibleAlternative:"Keep one accessible act, use assistance, or choose support without maintaining every course tool."},result:{question:"Did you do the next useful minimum?",observationPrompt:"What did you actually do, and what feedback remains relevant?"},judgment:{primary:{id:"stoic-6-decision",scenario:"Daniel checked which project examples meet the employer’s requirements. One relevant example still lacks an evidence sentence. His records show lunch drafts work, and he has ten minutes today.",question:"Which act most directly serves the priority?",options:[{id:"draft-relevant",text:"Produce one relevant evidence sentence at the tested lunch cue, with an accessible backup if needed.",feedback:"This keeps the relevant act and a condition supported by his records. It creates an observable piece without promising acceptance. Record the attempt and use later feedback."},{id:"advice-read",text:"Read application advice for ten minutes and choose an evidence task after reviewing more recommendations.",feedback:"Advice helps when information is missing. Here the needed example and a workable cue are known. More reading postpones producing the relevant piece this slot can hold."},{id:"check-relevance-again",text:"Review earlier evidence sentences and choose which one most closely matches the employer’s requirements.",feedback:"Checking relevance helps when requirements or fit are unclear. Daniel already checked them, and this example lacks its sentence. Use the available drafting slot; check again if the requirements change."}],bestOptionId:"draft-relevant"}},carry:{takeaway:"Keep the useful act and a workable condition. Let feedback improve what comes next.",followUp:{questionId:"stoic-6-return",question:"Did your chosen condition help, fail, stay untested, or leave you unsure?",observationPrompt:"Which condition occurred, and what act did you actually attempt?",adjustmentPrompt:"Repeat, change one condition, get support, or stop?"}},goDeeper:{sections:[{heading:"Consolidation uses relevant evidence",paragraphs:["Epictetus’s distinction is philosophical guidance for effort [S09]. It does not require ignoring the results of an action. A reply, a failed access route, or a repeated conflict can inform what you try next. You cannot determine an employer’s decision alone, but you can use appropriate feedback and seek assistance. Your record should include the act and relevant outcome without turning either into a verdict about your whole character.","Implementation-intention research supports linking a recognizable situation with an intended response across varied goals and settings [S03]. That structure is useful only when the response is feasible and relevant. “After lunch, write one usable project evidence sentence” is a concrete act. “After lunch, make the employer approve” is an external outcome. Preparing or reading advice may be suitable, but label it honestly. The final lesson consolidates one continuing experiment rather than introducing another daily ritual or treating a completed course as proof of real-world practice."]},{heading:"A wish, an obstacle, and a feasible response",paragraphs:["Wang and colleagues reviewed mental contrasting with implementation intentions [S04]. The sequence names a feasible wish, its desired outcome, a present obstacle, and a specific if–then response. Across 21 articles with 24 independent estimates and 15,907 participants, average goal attainment improved by g = 0.336, with a 95% confidence interval of 0.229 to 0.443. Heterogeneity was substantial, I² = 59.3%, and study quality varied. This is a contemporary estimate for the combined sequence, not a universal success rate.","ODA’s brief use of the sequence and weekly record review are adaptations. No universal dose or efficacy for this exact flow was established. Choose an act that addresses the actual priority, rather than easy busywork or every exercise in the course. If the obstacle is external danger, missing resources, illness, or a care demand, the response may be support, a boundary, rest, or stopping the goal. Record the next attempt separately from its plan and review. Unchanged emotion and an uncertain external outcome do not erase a reported useful act."]}],sourceIds:["stoic-epictetus-iep","stoic-planning","stoic-mcii"]}}],c=[{id:"stoic-1",practice:["Choose one goal and separate a feasible act, needed support, and external outcomes.","Name a recognizable opening and useful minimum.","Do the act, or explicitly name preparation and its later use."],correct:1,photo:{id:"1507525428034-b723cf961d3e",alt:"A calm shoreline where clear water meets the sand"}},{id:"stoic-2",practice:["Separate one fact from an unverified interpretation.","Check evidence on both sides without minimizing actual harm.","Use a grounded clarification, factual correction, or safe protective response."],correct:2,photo:{id:"1500534314209-a25ddb2bd429",alt:"Layers of hazy hills at dusk"}},{id:"stoic-3",practice:["Choose a mild realistic obstacle for your existing act; imagery is optional.","Plan one feasible response and stop if distress grows.","Use the response when needed and record whether the obstacle occurred."],correct:1,photo:{id:"1464822759023-fed622ff2c3b",alt:"Forested valleys below snowy mountains"}},{id:"stoic-4",practice:["Choose a mild everyday situation and optionally coach yourself by name for 60 seconds.","Stop or skip if panic, dissociation, or intrusive memories arise.","Use one factual sentence, request, or safe boundary and record it."],correct:0,photo:{id:"1506905925346-21bda4d32df4",alt:"Mountain ridges seen from above a sea of clouds"}},{id:"stoic-5",practice:["Review one actual attempt, naming a useful part and a specific mismatch.","Choose one correction; shorten, move, or stop a punitive or sleep-disrupting review.","Use the correction in a real act and record it separately from reviewing."],correct:1,photo:{id:"1475924156734-496f6cac6ec1",alt:"Waves on a rocky shore at dusk"}},{id:"stoic-6",practice:["Compare actual attempts for your existing goal and act.","Keep the useful minimum and change at most one condition.","Try the next relevant act, record it, and leave extra tools optional."],correct:2,photo:{id:"1502082553048-f009c37129b9",alt:"A single tree standing in an open landscape"}}],d={id:"stoic",title:"Checking again? Give your next useful act a turn",subtitle:"6 lessons to act under uncertainty, check your interpretations, and carry one workable experiment into next week.",description:"Choose one goal that uncertainty is crowding out. Use Stoic distinctions and optional psychological tools to make a grounded act, review it, and adapt.",scope:"For adults who want steadier responses to stress, setbacks and uncertainty. Stoicism here does not mean suppressing emotions or putting on a brave face; feelings are welcome, and the practice is about what you do next. This is education and self-practice, not therapy, and it is not a substitute for treatment. If you live with anxiety, depression, trauma or intrusive worry, some exercises, especially imagining setbacks, may not suit you; please work with a qualified professional. If you are in crisis or thinking about harming yourself, contact your local emergency number now.",outcome:"One goal-linked experiment with actual acts, honest reviews, and a next-week plan that includes support and boundaries.",photo:{id:"1439066615861-d1af74d74000",alt:"A wooden pier on a still mountain lake"},lessons:r.map((e,s)=>{const n=c[s],t=e.judgment.primary,i=t.options.find(a=>a.id===t.bestOptionId),o=t.options.filter(a=>a.id!==t.bestOptionId).map(a=>a.text);return o.splice(n.correct,0,i.text),{...n,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${t.scenario} ${t.question}`,options:o,feedback:i.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})};export{d as COURSE,l as SOURCES,r as STOIC_LESSONS_V2};
